"""Load the golden fixtures (fixtures/*.json) as validated models. Fixtures are generated by scripts/make_fixtures.py."""
from __future__ import annotations

import json
from functools import lru_cache
from typing import Any, Type, TypeVar

from pydantic import TypeAdapter

from . import settings

M = TypeVar("M")


@lru_cache(maxsize=None)
def raw(name: str) -> Any:
    """Parsed JSON of fixtures/<name>.json (cached; do not mutate the result, deep-copy it)."""
    with open(settings.FIXTURES_DIR / f"{name}.json", encoding="utf-8") as f:
        return json.load(f)


def load(name: str, model: Type[M]) -> M:
    """A fresh, validated instance (safe to mutate). `model` may be a pydantic model or e.g. list[Leg]."""
    return TypeAdapter(model).validate_python(json.loads(json.dumps(raw(name))))
